import json
from collections import Counter

import duckdb
import pandas as pd

DB = 'data/scisci_process.duckdb'

KTP_XLSX_MATCH_COL = 'ktp.xlsx_match'
KTP_DOCX_TABLE_1_PREFIX = 'ktp.table_1_'
KTP_DOCX_OPTIONAL_EMPTY_COLS = {
    'ktp.table_1_socioeconomic_status',
    'ktp.table_1_race_ethnicity_language_culture',
    'ktp.table_1_topics',
    'ktp.table_1_footnotes',
    'ktp.table_1_comments',
}
KTP_TABLE_1_EMPTY_VALUE_PLACEHOLDERS = {'-', '–', '—', '−', 'NR'}
KTP_XLSX_MATCH_SOURCE_KEY_TOKENS_KEY = 'ktp.source_key_first_name_norm_tok'
KTP_XLSX_MATCH_SOURCE_KEY_LAST_KEY = 'ktp.source_key_last_name_norm'
KTP_XLSX_MATCH_FIRST_TOKENS_KEY = 'ktp.first_name_norm_tok'
KTP_XLSX_MATCH_LAST_NAME_NORM_KEY = 'ktp.last_name_norm'


def loads_jsonlines(payload):
    return [json.loads(line) for line in str(payload or '').splitlines() if line.strip()]


def has_present_xlsx(value):
    if value is None:
        return False
    if isinstance(value, str):
        return bool(value.strip())
    return not bool(pd.isna(value))


def is_exact_xlsx(value):
    # This mirrors src/steps/step_10_build_cards.py::_is_exact_xlsx_match_payload.
    if value is None:
        return True
    if not isinstance(value, str):
        return True
    raw = value.strip()
    if not raw:
        return True
    try:
        payload = json.loads(raw)
    except json.JSONDecodeError:
        return False
    if not isinstance(payload, dict):
        return False

    source_key_tokens = payload.get(KTP_XLSX_MATCH_SOURCE_KEY_TOKENS_KEY, [])
    source_key_last = payload.get(KTP_XLSX_MATCH_SOURCE_KEY_LAST_KEY)
    first_tokens = payload.get(KTP_XLSX_MATCH_FIRST_TOKENS_KEY, [])
    last_name_norm = payload.get(KTP_XLSX_MATCH_LAST_NAME_NORM_KEY)
    if not isinstance(source_key_tokens, list):
        source_key_tokens = []
    if not isinstance(first_tokens, list):
        first_tokens = []

    source_key_last_str = str(source_key_last).strip() if source_key_last is not None else ''
    last_name_norm_str = str(last_name_norm).strip() if last_name_norm is not None else ''
    source_key_token_values = sorted(
        {str(token).strip() for token in source_key_tokens if str(token).strip()}
    )
    if not source_key_token_values or not source_key_last_str:
        return False
    first_token_values = sorted(
        {str(token).strip() for token in first_tokens if str(token).strip()}
    )
    return (
        source_key_token_values == first_token_values
        and bool(last_name_norm_str)
        and source_key_last_str == last_name_norm_str
    )


def is_non_empty_table1_value(value):
    if value is None:
        return False
    if isinstance(value, str):
        normalized = value.strip()
        return bool(normalized) and normalized not in KTP_TABLE_1_EMPTY_VALUE_PLACEHOLDERS
    return not bool(pd.isna(value))


def docx_row_complete(row):
    required_cols = [
        col
        for col in row
        if col.startswith(KTP_DOCX_TABLE_1_PREFIX) and col not in KTP_DOCX_OPTIONAL_EMPTY_COLS
    ]
    if not required_cols:
        return True
    return all(is_non_empty_table1_value(row.get(col)) for col in required_cols)


conn = duckdb.connect(DB, read_only=True)
namekeys = [row[0] for row in conn.execute('SELECT name_key FROM outerdict_stub').fetchall()]
xlsx_by_key = {
    key: loads_jsonlines(payload)
    for key, payload in conn.execute('SELECT name_key, innerdicts FROM xlsx_innerdicts').fetchall()
}
docx_by_key = {
    key: loads_jsonlines(payload)
    for key, payload in conn.execute('SELECT name_key, innerdicts FROM docx_innerdicts').fetchall()
}
ssn_count_by_key = dict(
    conn.execute('SELECT "ktp.source_key", COUNT(*) FROM ssn_innerdicts GROUP BY 1').fetchall()
)

partition_counts = Counter()
xlsx_fail_by_partition = Counter()
rule_counts = Counter()

for key in namekeys:
    xlsx_rows = xlsx_by_key.get(key, [])
    docx_rows = docx_by_key.get(key, [])
    sciscinet_count = ssn_count_by_key.get(key, 0)

    xlsx_payloads = [row.get(KTP_XLSX_MATCH_COL) for row in xlsx_rows]
    xlsx_any = any(has_present_xlsx(value) for value in xlsx_payloads)
    xlsx_non_exact_any = any(
        has_present_xlsx(value) and not is_exact_xlsx(value) for value in xlsx_payloads
    )
    xlsx_exact_ok = xlsx_any and not xlsx_non_exact_any

    docx_any = bool(docx_rows)
    docx_complete_ok = docx_any and any(docx_row_complete(row) for row in docx_rows)
    sciscinet_exactly_one_ok = sciscinet_count == 1
    subset1_ok = sciscinet_exactly_one_ok and xlsx_exact_ok and docx_complete_ok

    rule_counts['subset1' if subset1_ok else 'subset2'] += 1
    rule_counts['xlsx_pass' if xlsx_exact_ok else 'xlsx_fail'] += 1
    rule_counts['docx_pass' if docx_complete_ok else 'docx_fail'] += 1
    rule_counts['sciscinet_pass' if sciscinet_exactly_one_ok else 'sciscinet_fail'] += 1

    if subset1_ok:
        partition = 'subset1_excluded'
    elif sciscinet_exactly_one_ok and docx_complete_ok and (not xlsx_any or xlsx_non_exact_any):
        partition = 'xlsx_tier'
    elif sciscinet_exactly_one_ok and not docx_complete_ok:
        partition = 'docx_tier'
    else:
        partition = 'sciscinet_tier'

    partition_counts[partition] += 1
    if not xlsx_exact_ok:
        xlsx_fail_by_partition[partition] += 1

print('rule_counts', dict(sorted(rule_counts.items())))
print('partition_counts', dict(partition_counts))
print('xlsx_fail_by_partition', dict(xlsx_fail_by_partition), 'total', sum(xlsx_fail_by_partition.values()))
